320		if err := l2.Close(); err != nil {
321			t.Fatal(err)
322		}
323		if err := l3.Close(); err != nil {
324			t.Fatal(err)
325		}
326		assertOpenFails(t, path, ErrCorrupt)
327	
328		// 放回一份完好且与 l1 提交后等价（余额 30、p1 已扣款）的文件后，
329		// 立即恢复正常，读到的是该文件的内容。
330		fresh := filepath.Join(t.TempDir(), "fresh.json")
331		if err := CreateLedger(fresh, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}}); err != nil {
332			t.Fatal(err)
333		}
334		fl, err := Open(fresh)
335		if err != nil {
336			t.Fatal(err)
337		}
338		if _, err := fl.Submit(FeeBatch{FeeBps: 0, Intents: []PaymentIntent{
339			intent("p1", "aa", "usdc", 70),
340		}}); err != nil {
341			t.Fatal(err)
342		}
343		if err := fl.Close(); err != nil {
344			t.Fatal(err)
345		}
346		valid, err := os.ReadFile(fresh)
347		if err != nil {
348			t.Fatal(err)
349		}
350		writeFileAt(t, path, valid)
351	
352		l4, err := Open(path)
353		if err != nil {
354			t.Fatalf("reopen after restoring valid file: %v", err)
355		}
356		if bal, _ := l4.Balance("aa", "usdc"); bal != 30 {
357			t.Fatalf("restored ledger balance=%d want 30", bal)
358		}
359		snap, _ := l4.Query()
360		if len(snap.Settlements) != 1 || snap.Settlements[0].ID != "p1" {
361			t.Fatalf("restored ledger history: %+v", snap.Settlements)
362		}
363		if err := l4.Close(); err != nil {
364			t.Fatal(err)
365		}
366	}
367	
368	// 初始化后无句柄时删除文件，允许在同一路径重新初始化（文件确实不存在）；
369	// 文件存在时重新初始化仍报 ledger_exists，旧行为不变。
370	func TestCreateAfterExternalDeleteAndRejectExisting(t *testing.T) {
371		path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 500}})
372	
373		// 文件仍在：重复初始化拒绝，不覆盖。
374		if err := CreateLedger(path, []BalanceInit{{Account: "zz", Asset: "usdc", Balance: 1}}); KindOf(err) != ErrExists {
375			t.Fatalf("re-init existing file want %s, got %v", ErrExists, err)
376		}
377	
378		if err := os.Remove(path); err != nil {
379			t.Fatal(err)
380		}
381		// 文件已被外部删除且无活动句柄：允许重新初始化。
382		if err := CreateLedger(path, []BalanceInit{{Account: "cc", Asset: "usdc", Balance: 9}}); err != nil {
383			t.Fatalf("re-init after external delete: %v", err)
384		}
385		l, err := Open(path)
386		if err != nil {
387			t.Fatal(err)
388		}
389		if bal, _ := l.Balance("cc", "usdc"); bal != 9 {
390			t.Fatalf("re-initialized ledger balance=%d want 9", bal)
391		}
392		if bal, _ := l.Balance("aa", "usdc"); bal != 0 {
393			t.Fatalf("old init balance must not survive: aa/usdc=%d", bal)
394		}
395		l.Close()
396	}
