func TestRefundPayRefundPayReplay(t *testing.T) {
	path := newTestLedger(t, []BalanceInit{{Account: "aa", Asset: "usdc", Balance: 100}})
	l := openOrFail(t, path)
	must := func(batch FeeBatch) {
