			t.Fatalf("p2 fee accounting not preserved: %+v", snap.Settlements)
		}
		if len(snap.Refunds) != 1 || snap.Refunds[0].Charged != 49 {
			t.Fatalf("refund not preserved: %+v", snap.Refunds)
		}
